// HasIsolated reports whether an isolated presentation form exists.
func (f arabicForm) HasIsolated() bool { return f.isolated != 0 }

// HasFinal reports whether a final presentation form exists.
func (f arabicForm) HasFinal() bool { return f.final != 0 }

// HasInitial reports whether an initial presentation form exists.
func (f arabicForm) HasInitial() bool { return f.initial != 0 }

// HasMedial reports whether a medial presentation form exists.
func (f arabicForm) HasMedial() bool { return f.medial != 0 }

