// arabicFormOf returns the Presentation Forms-B entry for r.
// ok is false when r has no Presentation Forms-B entries.
func arabicFormOf(r rune) (arabicForm, bool) {
	lo, hi := 0, len(arabicForms)-1
	for lo <= hi {
		mid := (lo + hi) >> 1
		switch {
		case arabicForms[mid].base == r:
			return arabicForms[mid].form, true
		case arabicForms[mid].base < r:
			lo = mid + 1
		default:
			hi = mid - 1
		}
	}
	return arabicForm{}, false
}

// shapedRune returns the Presentation Forms-B glyph for r according to its
// joining state (rightJoined and leftJoined).
//
// Logical Preservation Contract:
// If the required presentation form glyph is absent (0x0000) or r has no
// presentation forms at all, shapedRune returns r unchanged.
// For example, U+0649 (Alef Maksura, JT=D) has isolated (0xFEEF) and final (0xFEF0)
// forms, but no initial or medial glyphs in Presentation Forms-B; when in initial
// or medial position, it returns 0x0649 unchanged.
func shapedRune(r rune, rightJoined, leftJoined bool) rune {
	form, ok := arabicFormOf(r)
	if !ok {
		return r
	}
	var shaped rune
	switch {
	case rightJoined && leftJoined:
		shaped = form.medial
	case rightJoined && !leftJoined:
		shaped = form.final
	case !rightJoined && leftJoined:
		shaped = form.initial
	default:
		shaped = form.isolated
	}
	if shaped == 0 {
		return r
	}
	return shaped
}

// lamAlefEntry maps one Alef variant to its Lam-Alef ligature forms.
// The Lam base (U+0644) is implicit.
type lamAlefEntry struct {
	alef               rune // Alef variant
	isolated, finalLig rune // ligature glyphs
}

// lamAlefForms lists the 4 Lam-Alef ligatures, sorted by Alef variant.
// Source: UnicodeData-17.0.0.txt (2-codepoint decompositions 0644+<alef>).
var lamAlefForms = [...]lamAlefEntry{
	{0x0622, 0xFEF5, 0xFEF6}, // Lam + U+0622
	{0x0623, 0xFEF7, 0xFEF8}, // Lam + U+0623
	{0x0625, 0xFEF9, 0xFEFA}, // Lam + U+0625
	{0x0627, 0xFEFB, 0xFEFC}, // Lam + U+0627
}

// lamAlefFormOf returns the ligature forms for a Lam followed by alef.
// ok is false if alef is not one of the recognised Alef variants.
func lamAlefFormOf(alef rune) (isolated, final rune, ok bool) {
	for i := range lamAlefForms {
		if lamAlefForms[i].alef == alef {
			return lamAlefForms[i].isolated, lamAlefForms[i].finalLig, true
		}
	}
	return 0, 0, false
}

// missingFormEntry records a letter whose Joining_Type is D but that has
// no independent initial/medial Presentation Forms-B glyphs.
// Under the Logical Preservation Contract, when shaped into initial or medial
// position, these letters remain their original logical rune.
type missingFormEntry struct {
	base rune
	note string
}

