// isMissingForm reports whether r is a dual-joining letter that lacks
// initial/medial presentation forms.
func isMissingForm(r rune) bool {
	lo, hi := 0, len(missingForms)-1
	for lo <= hi {
		mid := (lo + hi) >> 1
		switch {
		case missingForms[mid].base == r:
			return true
		case missingForms[mid].base < r:
			lo = mid + 1
		default:
			hi = mid - 1
		}
	}
	return false
}
